    [211814] = { enName = "Warsong Outrider Mark", enDescription = "You acquired this from a fallen Warsong Outrider combatant. Perhaps the Priestess of the Moon would be interested.", badIt = "Proof of winning a battle in Warsong Gulch", description = "L'hai ottenuto da un combattente dei Cavalcatori di Warsong caduto. Forse la Sacerdotessa della Luna potrebbe essere interessata." },
    [213735] = { enName = "Pristine G-7 C.O.R.E. Processor", itName = "Oggetto Sudicio", enDescription = "This thing can pre-render over 4 million gigaflops of low-variance relational codebursts. Wow!", badIt = "Tutta la sporcizia incrostata impedisce di capire che cosa sia davvero questo oggetto.", description = "Questo ogge può pre-renderizzare oltre 4 milioni di gigaflop di codeburst relazionali a bassa varianza. Wow!" },
    [213736] = { enName = "Corroded G-7 C.O.R.E. Processor", itName = "Oggetto Sudicio", enDescription = "This processor core is caked with corrosion and a sticky black substance but you can barely make out a model number and a few illegible words through the gunk. You may need a specialist to help restore it.", badIt = "Tutta la sporcizia incrostata impedisce di capire che cosa sia davvero questo oggetto.", description = "Questo core del processore è incrostato di corrosione e di una sostanza nera appiccicosa, ma attraverso la sporcizia riesci a distinguere a malapena un numero di modello e qualche parola illeggibile. Potrebbe servirti uno specialista per ripristinarlo." },
    [216635] = { enName = "Spent Voidcore", itName = "Oggetto Sudicio", enDescription = "This seems to match the description of the voidcore that Wirdal needs, but it appears to be completely inert. There must be a way to recharge this...", badIt = "Tutta la sporcizia incrostata impedisce di capire che cosa sia davvero questo oggetto.", description = "Sembra corrispondere alla descrizione del nucleo del Vuoto che serve a Wirdal, ma pare completamente inattivo. Ci sarà un modo per ricaricarlo..." },
    [216636] = { enName = "Charged Voidcore", itName = "Oggetto Sudicio", enDescription = "This object seems to draw in all surrounding light and warmth. It is very cold to the touch.", badIt = "Tutta la sporcizia incrostata impedisce di capire che cosa sia davvero questo oggetto.", description = "Questo oggetto sembra attirare tutta la luce e il calore circostanti. È molto freddo al tatto." },
    [216645] = { enName = "Mote of Darkness", itName = "Oggetto Sudicio", enDescription = "Dark energy permeates this tiny floating speck of energy. Who knows what sort of amazing magics this could power?", badIt = "Tutta la sporcizia incrostata impedisce di capire che cosa sia davvero questo oggetto.", description = "L'energia oscura permea questa minuscola particella fluttuante di energia. Chissà quali magie straordinarie potrebbe alimentare?" },
